def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    result = new - old
    return {
        "value": result,
        "trace": {
            "old_2018": old,
            "new_2019": new,
            "difference": result,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares"
            }
        }
    }
